function leastInterval(tasks, n) {
  const left = new Array(26).fill(0);        // copies left of each letter
  const nextFree = new Array(26).fill(0);    // the earliest time each letter may run again
  for (const t of tasks) left[t.charCodeAt(0) - 65]++;
  let remaining = tasks.length, time = 0;
  while (remaining > 0) {
    let best = -1;
    for (let i = 0; i < 26; i++)             // the allowed task with the most copies left
      if (left[i] > 0 && nextFree[i] <= time && (best < 0 || left[i] > left[best])) best = i;
    if (best >= 0) {
      left[best]--;
      remaining--;
      nextFree[best] = time + n + 1;         // n units must pass before it runs again
    }                                        // otherwise the CPU idles for this unit
    time++;
  }
  return time;
}

