import heapq
from collections import Counter, deque

def least_interval(tasks, n):
    ready = [-c for c in Counter(tasks).values()]   # copies left per task, negated: most first
    heapq.heapify(ready)
    cooling = deque()                        # (copies left, time it may run again), oldest first
    time = 0
    while ready or cooling:
        time += 1
        if ready:
            left = -heapq.heappop(ready) - 1 # run the task with the most copies left
            if left > 0:
                cooling.append((left, time + n))
        if cooling and cooling[0][1] == time:   # (if ready was empty, the CPU idled)
            heapq.heappush(ready, -cooling.popleft()[0])
    return time

int leastInterval(char[] tasks, int n) {
    int[] count = new int[26];
    for (char t : tasks) count[t - 'A']++;
    PriorityQueue<Integer> ready = new PriorityQueue<>(Collections.reverseOrder());   // copies left, most first
    for (int c : count) if (c > 0) ready.offer(c);
    ArrayDeque<int[]> cooling = new ArrayDeque<>();   // {copies left, time it may run again}
    int time = 0;
    while (!ready.isEmpty() || !cooling.isEmpty()) {
        time++;
        if (!ready.isEmpty()) {
            int left = ready.poll() - 1;              // run the task with the most copies left
            if (left > 0) cooling.offer(new int[]{left, time + n});
        }                                             // otherwise the CPU idles for this unit
        if (!cooling.isEmpty() && cooling.peek()[1] == time) ready.offer(cooling.poll()[0]);
    }
    return time;
}

int leastInterval(vector<char>& tasks, int n) {
    int count[26] = {0};
    for (char t : tasks) count[t - 'A']++;
    priority_queue<int> ready;                        // copies left per task, most first
    for (int c : count) if (c > 0) ready.push(c);
    queue<pair<int, int>> cooling;                    // (copies left, time it may run again)
    int time = 0;
    while (!ready.empty() || !cooling.empty()) {
        time++;
        if (!ready.empty()) {
            int left = ready.top() - 1;               // run the task with the most copies left
            ready.pop();
            if (left > 0) cooling.push({left, time + n});
        }                                             // otherwise the CPU idles for this unit
        if (!cooling.empty() && cooling.front().second == time) {
            ready.push(cooling.front().first);
            cooling.pop();
        }
    }
    return time;
}

function leastInterval(tasks, n) {
  const count = new Array(26).fill(0);
  for (const t of tasks) count[t.charCodeAt(0) - 65]++;
  const most = Math.max(...count);                     // copies of the busiest task
  const tied = count.filter((c) => c === most).length; // tasks that share that count
  return Math.max(tasks.length, (most - 1) * (n + 1) + tied);
}

from collections import Counter

def least_interval(tasks, n):
    counts = Counter(tasks).values()
    most = max(counts)                                 # copies of the busiest task
    tied = sum(1 for c in counts if c == most)         # tasks that share that count
    return max(len(tasks), (most - 1) * (n + 1) + tied)

int leastInterval(char[] tasks, int n) {
    int[] count = new int[26];
    for (char t : tasks) count[t - 'A']++;
    int most = 0, tied = 0;
    for (int c : count) {
        if (c > most) { most = c; tied = 1; }          // a new busiest task
        else if (c == most) tied++;                    // another task with that count
    }
    return Math.max(tasks.length, (most - 1) * (n + 1) + tied);
}

